import json
def users(f):
    out=[]
    for line in open(f):
        try: d=json.loads(line)
        except: continue
        if d.get('type')!='user': continue
        m=d.get('message',{}); c=m.get('content'); txt=''
        if isinstance(c,str): txt=c
        elif isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='text': txt+=b['text']
        txt=txt.strip()
        if not txt: continue
        if '<system-reminder>' in txt:
            txt=txt.split('<system-reminder>')[0].strip()
        if not txt: continue
        if txt.startswith('Base directory for this skill') or txt.startswith('<task-notification') or txt.startswith('[Request interrupted') or txt.startswith('<command-') or txt.startswith('<local-command'): continue
        out.append((d.get('timestamp',''),txt))
    return out
for f in ['.sessions/f4492b01-e778-4d0a-938d-4455205b3635.jsonl']:
    print('='*20,f)
    for ts,t in users(f):
        print(f'--- {ts}\n{t[:1500]}')
EOF

